  const snapshot = useSyncExternalStore(canWindow ? geometry.subscribeInline : subscribeToNothing, canWindow ? geometry.getSnapshot : getUnmeasured, canWindow ? geometry.getServerSnapshot : getUnmeasured);
  const [tracking, setTracking] = useState();
